// Target Business Categories in Bengaluru
const categories = [
  { niche: "Travel Operators & Tour Cabs", area: "Koramangala, Bengaluru", targetTicket: "₹8,000" },
  { niche: "Homestays & Resorts", area: "Bengaluru Outskirts / Sakleshpur", targetTicket: "₹10,000" },
  { niche: "Dental & Wellness Clinics", area: "Indiranagar, Bengaluru", targetTicket: "₹8,000" },
  { niche: "Packers & Movers / Car Rentals", area: "HSR Layout, Bengaluru", targetTicket: "₹6,000" }
];

return categories.map(cat => ({ json: cat }));

// Sample local businesses scraped or retrieved via Google Places API
// Validates whether website exists or requires modernization
const item = $input.item.json;

const sampleLeads = [
  {
    businessName: "Karnataka Wheels & Tours",
    category: item.niche,
    phone: "+919876543210",
    email: "info@karnatakawheels.example",
    websiteUrl: "",
    hasWebsite: false,
    status: "NO_WEBSITE"
  },
  {
    businessName: "Nandi Hills Valley Homestay",
    category: item.niche,
    phone: "+919845012345",
    email: "bookings@nandivalley.example",
    websiteUrl: "http://nandivalley.tripod.com",
    hasWebsite: true,
    isOutdated: true,
    status: "OUTDATED_SLOW_SITE"
  }
];

return sampleLeads.map(lead => ({ json: lead }));

const lead = $input.item.json;

// Tailored high-converting pitch citing Kiran's Yeshu Tours & Travels
const whatsappMessage = `Namaste ${lead.businessName} team! 🙏\n\nI saw your listing in Bengaluru for ${lead.category}. I noticed you don't have a modern mobile booking website yet (most customers today book straight from their phones on WhatsApp).\n\nI am a local web developer in Bengaluru. I recently built and launched yeshutoursandtravels.com—a fast mobile booking website with direct WhatsApp inquiry integration.\n\nI can deploy a modern, high-speed booking site for ${lead.businessName} in 4 days for just ₹8,000 (one-time), or help optimize and maintain your existing presence for ₹2,000/month.\n\nWould you like me to share a quick 1-minute demo preview of how your website would look?\n\nBest regards,\nKiran S R\nBengaluru | https://cipher-vortex.vercel.app`;

const cleanPhone = lead.phone.replace(/[^0-9]/g, '');
const whatsappLink = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(whatsappMessage)}`;

return {
  json: {
    ...lead,
    pitch: whatsappMessage,
    whatsappDirectLink: whatsappLink
  }
};
